const v4Ledger=[
['L01','协调 / 拆题','GLM',18200,2400,6200,'成功',1],['L02','Insight 查库','DeepSeek',24500,3800,10000,'成功',1],['L03','Media 研究','DeepSeek',28100,4200,8600,'成功',1],['L04','Query 新闻','DeepSeek',22400,3100,8200,'成功',1],['L05','verifier 核实','GLM',14300,1800,5000,'成功',2],['L06','advocate 质疑','GLM',13700,2100,4800,'成功',1],['L07','Report 成稿','GLM',34200,6200,14300,'成功',1],['L08','sentinel 值守','DeepSeek',4200,600,1400,'成功',1],['L09','verifier 核实','GLM',500,0,100,'失败后重试',1],['L10','Media 研究','DeepSeek',null,null,null,'超时 / usage 缺失',2]
].map((r,i)=>({id:r[0],role:r[1],provider:r[2],input:r[3],output:r[4],cache:r[5],status:r[6],attempt:r[7],run:'RUN-1017-003',time:'10:'+String(10+i).padStart(2,'0'),source:r[3]===null?'未返回':'供应商回传样例'}));
const v4Prices={GLM:{input:3,cache:.5,output:12},DeepSeek:{input:2,cache:.2,output:8}};
function v4Cost(r){if(r.input===null)return null;const p=v4Prices[r.provider];return ((r.input-r.cache)*p.input+r.cache*p.cache+r.output*p.output)/1e6;}
function v4Totals(rows=v4Ledger){const t={input:0,output:0,cache:0,cost:0,unknown:0,calls:rows.length,failedCost:0};for(const r of rows){if(r.input===null){t.unknown++;continue;}t.input+=r.input;t.output+=r.output;t.cache+=r.cache;const c=v4Cost(r);t.cost+=c;if(r.status.includes('失败'))t.failedCost+=c;}t.total=t.input+t.output;t.uncached=t.input-t.cache;return t;}
