function v4Go(id){if(typeof parkBack==='function')parkBack();showPage(id);links.forEach(a=>a.classList.toggle('on',a.dataset.p===id));if(id==='chat')v4RenderChat();if(id==='usage')v4RenderUsage();if(id==='keys')v4RenderKeys();if(id==='custom')renderCustom();}
function v4Session(){return v4Sessions.find(s=>s.id===v4State.session)||v4Sessions[0];}
function v4Report(){return v4Reports[v4Session().report]||null;}
function v4SessionTokens(){return Math.ceil(v4Session().messages.reduce((n,m)=>n+m.text.length,0)/2);}
function v4MessageHTML(m){return `<div class="v4-message ${m.role==='user'?'user':''}"><span class="v4-msg-avatar">${m.role==='user'?'你':'谛'}</span><div class="v4-msg-content"><div class="v4-author">${m.role==='user'?'你':'主 Agent · 本地演示答复'}</div><div class="v4-message-text">${v4Esc(m.text).replace(/\n/g,'<br>')}</div>${m.refs?.length?`<div class="v4-chat-evidence">${m.refs.map(id=>`<button data-v4-evidence="${id}">↗ ${id} · 查看依据</button>`).join('')}</div>`:''}${m.research?'<div class="v4-report-actions"><button class="btn dark" onclick="v4StartResearch()">◈ 打开研究草案</button></div>':''}</div></div>`;}
function v4Composer(quick=false){return `<div class="v4-chat-footer"><div class="v4-prompt-row">${['这份报告的核心结论是什么？','还有哪些证据缺口？','舆情研判是什么？','Token 费用怎么算？'].map(q=>`<button data-v4-prompt="${v4Esc(q)}">${q}</button>`).join('')}</div><form class="v4-chat-form"><div class="v4-composer"><textarea name="question" aria-label="${quick?'随时问输入':'对话输入'}" placeholder="问报告、问基础问题，或补充研究线索…（Enter 发送，Shift+Enter 换行）" maxlength="3000" required></textarea><button class="btn dark" type="submit" style="padding:11px 13px">发送 ↑</button></div></form><div class="v4-chat-footnote"><span>⚡</span><select aria-label="对话模型" onchange="v4State.model=this.value;v4RefreshStreams()">${['GLM-5.3-Flash / LiteLLM','GLM / BigModel','DeepSeek / 官方 API'].map(m=>`<option ${m===v4State.model?'selected':''}>${m}</option>`).join('')}</select><span data-v4-chat-tokens>本会话估算 ${v4SessionTokens()} tok</span><a href="#" onclick="event.preventDefault();v4Go('usage')">查看账本</a></div><div class="v4-label" style="font-size:9px;margin-top:5px">演示模式 · 未连接真实模型 · 会话估算不计入供应商账单</div></div>`;}
function v4ContextHTML(){const r=v4Report();return `<h3 style="font-size:13px;margin-bottom:4px">本次对话上下文</h3><div class="v4-context-card"><h4>📄 ${r?'关联报告':'基础问答'}</h4><p>${r?v4Esc(r.title):'不强制绑定议题，可以直接询问基础问题。'}</p><button class="btn" onclick="v4AttachReport()" style="font-size:10px">${r?'切换报告':'关联一份报告'}</button>${r?'<button class="btn" onclick="v4SelectSession(\'general\')" style="font-size:10px;margin-left:4px">取消关联</button>':''}</div><div class="v4-context-card green"><h4>🔗 引用可回看</h4><p>针对当前 AI 研究的回答可引用原文证据编号；缺少原文时明确说明。</p><button class="btn" onclick="v4Go('research')" style="font-size:10px">查看研判与证据</button></div><div class="v4-context-card orange"><h4>⚡ 用量与路由</h4><p>对话模型可切换。实际 usage、缓存命中和费用在账本中分别统计。</p><div class="v4-flex"><button class="btn" onclick="v4Go('llm')" style="font-size:10px">LLM 配置</button><button class="btn" onclick="v4Go('usage')" style="font-size:10px">Token 账本</button></div></div>`;}
function v4RenderChat(){const s=v4Session();v4State.mode=s.mode;document.getElementById('p-chat').innerHTML=`<div class="topbar"><h1>💬 对话中心</h1><span class="sub">报告追问 · 基础问答 · 研究协作</span><button class="btn" style="margin-left:auto" onclick="v4Go('research')">◈ 研判工作台</button></div><div class="v4-note">对话是始终保留的用户入口。可以直接问基础问题，也可以关联报告追问依据、局限或后续研究；子 Agent 由主 Agent 协调。</div><div class="v4-chat-mode">${[['report','📄 报告追问'],['general','💡 基础问答'],['research','◈ 研究助手']].map(([id,t])=>`<button class="${s.mode===id?'on':''}" data-v4-mode="${id}">${t}</button>`).join('')}</div><div class="v4-chat-layout"><aside class="v4-chat-sessions"><button class="newchat" onclick="v4NewSession()">＋ 新建对话</button><div class="v4-label">会话历史 · 本页内存</div>${v4Sessions.map(x=>`<button class="v4-session ${x.id===s.id?'active':''}" data-v4-session="${x.id}"><strong>${x.mode==='report'?'📄':x.mode==='general'?'💡':'◈'} ${v4Esc(x.title)}</strong><small>${x.messages.length} 条消息 · ${x.report?'关联报告':'自由对话'}</small></button>`).join('')}</aside><section class="v4-conversation"><div class="v4-chat-header"><div class="v4-flex"><span class="v4-agent-mark">谛</span><div><b style="font-size:13px">${v4Esc(s.title)}</b><div class="v4-label">${v4Report()?v4Esc(v4Report().title):'你可以直接提问，不需要先创建研究任务'}</div></div></div>${v4Tag(s.report?'报告上下文':'自由问答',s.report?'p':'g')}</div><div class="v4-chat-messages" data-v4-chat-stream>${s.messages.map(v4MessageHTML).join('')}</div>${v4Composer()}</section><aside class="v4-chat-context">${v4ContextHTML()}</aside></div>`;}
function v4RefreshStreams(){const s=v4Session();document.querySelectorAll('[data-v4-chat-stream]').forEach(el=>{el.innerHTML=s.messages.map(v4MessageHTML).join('');el.scrollTop=el.scrollHeight;});document.querySelectorAll('[data-v4-chat-tokens]').forEach(el=>el.textContent='本会话估算 '+v4SessionTokens()+' tok');}
function v4RenderQuick(){const root=document.getElementById('v4-quick-root');if(!v4State.quick){root.innerHTML='';return;}root.innerHTML=`<section class="v4-quick" aria-label="随时问对话窗口"><div class="v4-chat-header"><div class="v4-flex"><span class="v4-agent-mark">谛</span><div><b style="font-size:13px">随时问</b><div class="v4-label">${v4Report()?v4Esc(v4Report().title):'基础问答 / 使用帮助'}</div></div></div><div class="v4-flex"><button class="btn" onclick="v4State.quick=false;v4RenderQuick();v4Go('chat')">展开 ↗</button><button class="v4-close" onclick="v4ToggleQuick()" aria-label="关闭随时问">×</button></div></div><div class="v4-chat-messages" data-v4-chat-stream>${v4Session().messages.map(v4MessageHTML).join('')}</div>${v4Composer(true)}</section>`;v4RefreshStreams();}
function v4ToggleQuick(){v4State.quick=!v4State.quick;v4RenderQuick();if(v4State.quick)document.querySelector('#v4-quick-root textarea')?.focus();}
function v4SelectSession(id){if(!v4Sessions.some(s=>s.id===id))return;v4State.session=id;v4State.mode=v4Session().mode;v4RenderChat();if(v4State.quick)v4RenderQuick();}
function v4NewSession(){const id='session-'+Date.now();v4Sessions.unshift({id,title:'新的基础对话',mode:'general',report:null,messages:[{role:'assistant',text:'新的对话已经准备好。你可以问基础问题，或关联一份报告继续追问。',refs:[]}]});v4State.session=id;v4RenderChat();v4RenderQuick();}
function v4AskReport(id='ai'){if(!v4Reports[id])id='ai';let s=v4Sessions.find(x=>x.report===id);if(!s){s={id:'report-'+id,title:v4Reports[id].title,mode:'report',report:id,messages:[{role:'assistant',text:'已关联报告「'+v4Reports[id].title+'」。你可以追问核心判断、证据来源、统计口径或局限。'+(id!=='ai'?'这份历史报告仅保留原版演示内容，当前没有其真实原文证据包。':''),refs:[]}]};v4Sessions.unshift(s);}v4State.session=s.id;v4Go('chat');v4State.quick=false;v4RenderQuick();}
function v4AttachReport(){v4Modal('选择对话关联的报告',Object.entries(v4Reports).map(([id,r])=>`<button class="v4-session" onclick="v4CloseModal();v4AskReport('${id}')"><strong>📄 ${r.title}</strong><small>${r.kind} · ${r.desc}</small></button>`).join(''));}
function v4Answer(q){const s=v4Session(),ai=s.report==='ai',legacy=s.report&&s.report!=='ai';if(/^(你好|您好|嗨|hello|hi)[！!。\s]*$/i.test(q))return {text:'你好，我是谛听的主 Agent。你可以问报告的结论与依据，也可以问基础概念、模型配置或 Token 费用。你想先聊哪一项？'};
 if(/缺口|不足|争议|局限|不确定/.test(q)&&s.report){if(legacy)return {text:'这份原版演示报告需要补充真实证据包后才能逐条核查。目前可检查的边界包括：统计的时间窗与平台范围、是否存在同源转载、情感样本是否足够，以及推断是否超出原文。不能把卡片上的数字直接当成已核实事实。'};const gaps=v4Research.claims.filter(c=>['disputed','pending'].includes(c.status));return {text:gaps.length?'当前保留的缺口与争议：\n'+gaps.map(c=>'• '+c.title).join('\n')+'\n\n这些问题不会因为成稿而自动变成确定结论。下一步应补充独立原文或行为样本。':'当前结论仍需保持时间、平台与样本限定。门禁通过表示满足本轮交付要求，不等于获得全局真值保证。',refs:['E05']};}
 if(/总结|核心|结论|概括/.test(q)&&s.report){if(legacy)return {text:'当前关联的是「'+v4Reports[s.report].title+'」。这是 v2 保留的历史演示卡片；我可以帮助拆解报告结构、核查所需材料和后续提问，但缺少其真实原文证据包，不能进一步验证其中的事实与数字。\n\n建议先确认：报告研究了什么、哪些事实有原文、哪些只是观点或预测。'};return {text:'这份研究目前可以这样概括：\n'+v4Research.claims.filter(c=>['supported','qualified'].includes(c.status)).slice(0,3).map(c=>'• '+c.title).join('\n')+'\n\n企业采用意愿和跨社区总体情绪仍需更多证据，不能由讨论热度直接推出。',refs:['E01','E03','E05']};}
 if(/210|增长率|数字|分母|怎么算|计算口径/.test(q)&&!/token|费用|消费|计费|缓存/i.test(q))return {text:'示例关注指数的计算：\n基期 26.0，当前 80.6。\n增长率 = (80.6 − 26.0) ÷ 26.0 × 100% = 210%。\n当前是基期的 3.1 倍。\n\n这项指标由同源覆盖下的榜位计算，不等于帖子数增长，也不代表所有公众态度。',refs:ai?['E03']:[]};
 if(/token|缓存|消费|计费|费用/i.test(q))return {text:'Token 与费用应分开看：\n• 总 Token = 输入 + 输出。\n• 输入如果已经包含缓存命中，就不能再把缓存加到总量里。\n• 费用试算 = 未缓存输入 × 输入价 + 缓存输入 × 缓存价 + 输出 × 输出价。单价按每百万 Token 换算。\n• 失败、重试也可能计费；usage 未返回时标为未知，不能算零。\n\n仪表盘和「Token 与费用」页已恢复彩色图表、角色分账与可编辑演示单价。这里的会话字数估算不会冒充供应商实际账单。'};
 if(/证据|依据|来源|信源|核实/.test(q)&&s.report){if(legacy)return {text:'这份历史演示报告目前没有接入实际原文库，因此不能替它补造引用。正式流程需要：结论 ID → 支持/反驳证据 → 原文片段 → 抓取快照。建议先补齐证据包，再逐条核对。'};return {text:'可以从三类依据回看：\n• E01：官方发布资料，只支持明确发布事实与适用条件。\n• E03：固定窗口的代码统计，解释增长口径。\n• E05：独立行业观察，用于质疑“热度等于采用”的外推。\n\n多个转载网址可能属于同一个来源家族，不能重复当作独立确认。点击下方证据编号可查看示例原文。',refs:['E01','E03','E05']};}
 if(/mcp/i.test(q))return {text:'MCP 是模型/Agent 连接外部工具和资料的一种协议。这里可以配置热榜、检索、抓取等 MCP 服务的端点、传输方式与权限。MCP 解决“怎么连接”，不会自动替你实现舆情业务规则。你原来的 MCP 页面已完整保留，并补了可编辑的端点草稿。'};
 if(/skill|技能/i.test(q))return {text:'Skill 保存可复用的工作方法与领域规则，例如报告模板、证据引用和暗语识别说明。确定性计算、权限和写库校验应由代码实现。原来的十类 Skill 已保留，可查看、编辑本地规则草稿和开关。'};
 if(/tool|工具/i.test(q))return {text:'Tool 是 Agent 可调用的具体操作，例如 search.web、evidence.archive 或 crawl.deep。每个工具应定义参数、返回结构、超时与角色权限。Skill 说明如何使用能力，Tool 执行操作；MCP 可以作为工具接入形式。'};
 if(/harness|dsh|底座|agentteams/i.test(q))return {text:'本项目以 DeepSeek Harness 作为 Agent 运行底座。DiTing 自己负责舆情采集、证据、门禁规则和报告产品。第三方 AgentTeams 是可选的团队协作插件，与官方团队机制分别验证。配置页会保留这些能力入口，不把它们从产品中删掉。'};
 if(/key|密钥|配置|模型|llm/i.test(q))return {text:'配置入口已经恢复：\n• LLM：供应商、Base URL、API Key、模型列表和角色路由。\n• MCP：端点、传输和权限。\n• Skill / Tool：规则与输入输出契约。\n• Key 与服务：检索 Key、Firecrawl、Jina、飞书、数据库和 BettaFish 七个 LLM 槽。\n\n原型里的密钥只保留本次页面内存，刷新清空；格式检查不等于真实连接测试。'};
 if(/舆情是什么|什么是舆情|舆情研判|基础|监测和研判/.test(q))return {text:'舆情是围绕一个事件、机构或议题，在公开传播中形成的观点、情绪与讨论。\n\n监测回答“发生了什么、哪些内容升温”；研判进一步回答“哪些事实可确认、分歧在哪里、可能影响什么、还有哪些未知”。热榜只是发现入口，不能代表全部公众。'};
 if(/研究|分析|监测|帮我查/.test(q))return {text:'可以把这个需求整理为研究草案：\n1. 明确对象、时间窗和平台范围。\n2. 分别核对原始事实、公开讨论与反例。\n3. 数字由代码统计，结论连接原文证据。\n4. 在预算内补证，缺证时交付明确的局限。\n\n点击下方进入研究草案；当前为演示，不会启动真实模型或采集。',research:true};
 const math=q.match(/^\s*(\d+(?:\.\d+)?)\s*([+\-*/×÷])\s*(\d+(?:\.\d+)?)\s*[=?？]?\s*$/);if(math){const a=Number(math[1]),b=Number(math[3]),op=math[2];return {text:((op==='/'||op==='÷')&&b===0)?'除数不能为零。':'计算结果：'+({'+':()=>a+b,'-':()=>a-b,'*':()=>a*b,'×':()=>a*b,'/':()=>a/b,'÷':()=>a/b}[op])()};}
 return {text:'已收到：“'+q+'”。当前本地原型可以演示报告结论、证据缺口、基础概念与配置帮助；这个问题还没有连接真实模型来生成开放式回答。\n\n你可以继续问“核心结论是什么”“有哪些证据不足”，或把问题整理成一个研究草案。',research:/查|研究|分析|找/.test(q)};
}
function v4Send(q){q=q.trim();if(!q)return;const s=v4Session();s.messages.push({role:'user',text:q,refs:[]});const answer=v4Answer(q);s.messages.push({role:'assistant',refs:[],...answer});v4State.estTokens+=Math.ceil((q.length+answer.text.length)/2);v4RenderChat();if(v4State.quick)v4RenderQuick();v4RefreshStreams();}
function v4StartResearch(){v4State.quick=false;v4RenderQuick();v4Go('research');document.getElementById('v4-research-frame').contentWindow.postMessage({kind:'diting-v4:new-research'},'*');}
function v4ShowEvidence(id){const e=v4Research.evidence.find(e=>e.id===id)||v4BaseEvidence.find(e=>e.id===id);if(!e)return;v4Modal(id+' / 对话引用依据',`<span class="pill g">示例归档片段</span><h3 style="margin:15px 0 8px">${v4Esc(e.title)}</h3><p>${v4Esc(e.source)}</p><div class="v4-note green">${v4Esc(e.quote)}</div><p class="v4-label">来源家族：${v4Esc(e.family||'来源家族待标记')}<br>这是一段演示材料，不是真实调查证据。</p><button class="btn dark" onclick="v4CloseModal();v4Go('research')">查看完整研判工作台</button>`);}

function v4Stacked(rows){const known=rows.filter(r=>r.input!==null),max=Math.max(...known.map(r=>r.input+r.output),1);return `<div class="v4-stacked-chart">${known.map(r=>{const total=r.input+r.output;return `<div class="v4-chart-col"><div class="v4-stack" style="height:${total/max*140}px"><i style="height:${r.output/total*100}%;background:#7c5cf0"></i><i style="height:${r.cache/total*100}%;background:#18a678"></i><i style="height:${(r.input-r.cache)/total*100}%;background:#3b6ef5"></i></div><small>${v4Esc(r.role.split(' ')[0])}</small></div>`;}).join('')}</div>`;}
function v4TokenSummary(){const t=v4Totals(),p1=t.uncached/t.total*100,p2=(t.uncached+t.cache)/t.total*100;return `<div class="v4-between"><div><h3>⚡ LLM Token 消耗与费用</h3><div class="v4-label">当前运行样例 · 输入含缓存 · 计算由代码完成</div></div><button class="btn dark" onclick="v4Go('usage')">查看完整账本 ↗</button></div><div class="v4-token-summary"><div><div class="v4-donut" style="background:conic-gradient(#3b6ef5 0 ${p1}%,#18a678 ${p1}% ${p2}%,#7c5cf0 ${p2}% 100%)"><div><b>${v4K(t.total)}</b>输入 + 输出</div></div><div class="v4-between"><span class="v4-label">费用试算</span><b style="color:#7c5cf0;font-size:20px">${v4Money(t.cost)}</b></div><div class="v4-label" style="margin-top:5px">演示单价 · 未知 usage ${t.unknown} 次不算零</div></div><div><div class="v4-legend"><span><i style="background:#3b6ef5"></i>未缓存输入 ${v4K(t.uncached)}</span><span><i style="background:#18a678"></i>缓存命中 ${v4K(t.cache)}</span><span><i style="background:#7c5cf0"></i>输出 ${v4K(t.output)}</span></div>${v4Stacked(v4Ledger.slice(0,8))}<div class="v4-label" style="margin-top:10px">缓存占输入 ${(t.cache/t.input*100).toFixed(1)}% · 失败调用费用已计入 · 此图不重复累加缓存</div></div></div>`;}
function v4UsageRows(){return v4State.usageFilter==='all'?v4Ledger:v4State.usageFilter==='unknown'?v4Ledger.filter(r=>r.input===null):v4Ledger.filter(r=>r.provider===v4State.usageFilter);}
function v4RenderUsage(){const rows=v4UsageRows(),t=v4Totals(rows);document.getElementById('p-usage').innerHTML=`<div class="topbar"><h1>⚡ Token 与费用账本</h1><span class="sub">保留原有彩色图表 · 按角色 / 模型 / 调用分账</span><button class="btn" style="margin-left:auto" onclick="v4PricesModal()">⚙ 单价配置</button></div><div class="v4-note">以下 usage 与单价均为演示数据。总量、缓存、失败费用由代码汇总；会话字数估算单列，不混入供应商回传账本。</div><div class="v4-metrics"><div class="v4-metric" style="--v4-color:#3b6ef5"><small>总 Token（输入 + 输出）</small><b>${v4K(t.total)}</b><small>输入 ${v4K(t.input)} · 输出 ${v4K(t.output)}</small></div><div class="v4-metric" style="--v4-color:#18a678"><small>缓存命中 / 已含在输入中</small><b>${v4K(t.cache)}</b><small>缓存占输入 ${t.input?(t.cache/t.input*100).toFixed(1):'0'}%</small></div><div class="v4-metric" style="--v4-color:#7c5cf0"><small>已知用量费用试算</small><b>${v4Money(t.cost)}</b><small>使用可编辑演示单价，不代表供应商定价</small></div><div class="v4-metric" style="--v4-color:#e8930c"><small>未知用量 / 不按零计费</small><b>${t.unknown}<span class="v4-unit"> 次</span></b><small>失败已知用量仍计费：${v4Money(t.failedCost)}</small></div></div><div class="v4-row"><div class="v4-panel"><h3>📊 角色 Token 构成</h3><div class="v4-legend"><span><i style="background:#3b6ef5"></i>未缓存输入</span><span><i style="background:#18a678"></i>缓存输入</span><span><i style="background:#7c5cf0"></i>输出</span></div>${v4Stacked(rows)}</div><div class="v4-panel"><h3>💰 角色费用分布</h3>${v4RoleCosts(rows,t)}</div></div><div class="v4-panel"><div class="v4-between"><h3>逐次调用账本</h3><span class="v4-source-tag">${rows.length} 次调用 · 来源可区分</span></div><div class="v4-filterbar">${[['all','全部'],['GLM','GLM / LiteLLM'],['DeepSeek','DeepSeek'],['unknown','usage 缺失']].map(([id,label])=>`<button class="${id===v4State.usageFilter?'active':''}" data-v4-usage="${id}">${label}</button>`).join('')}</div><div class="v4-scroll-table"><table><thead><tr><th>调用 / 时间</th><th>角色</th><th>路由</th><th>输入（含缓存）</th><th>缓存命中</th><th>输出</th><th>费用试算</th><th>状态 / 尝试</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="mono">${r.id}</b><br><span class="v4-label">${r.time}</span></td><td>${r.role}</td><td>${v4Tag(r.provider,r.provider==='GLM'?'p':'b')}</td><td>${r.input===null?'未知':v4Fmt(r.input)}</td><td style="color:#18a678">${r.cache===null?'未知':v4Fmt(r.cache)}</td><td style="color:#7c5cf0">${r.output===null?'未知':v4Fmt(r.output)}</td><td>${v4Money(v4Cost(r))}</td><td>${v4Esc(r.status)}<br><span class="v4-label">attempt ${r.attempt} · ${r.source}</span></td></tr>`).join('')}</tbody></table></div><div class="v4-note orange">输入若已包含缓存，未缓存输入 = 输入 − 缓存。费用 = [(输入 − 缓存) × 输入价 + 缓存 × 缓存价 + 输出 × 输出价] ÷ 1,000,000。未知用量单独挂账。</div></div><div class="v4-row"><div class="v4-panel"><h3>🧭 上下文与会话估算</h3><p class="v4-label">当前会话文本估算 ${v4SessionTokens()} tokens；本页所有演示对话新增估算 ${v4State.estTokens} tokens。</p><div class="v4-note">估算用于提示上下文，不作为供应商实际用量，也不参与上面的费用试算。</div></div><div class="v4-panel"><h3>🧾 外部调用费用</h3><p class="v4-label">Tavily / Anspire / Bocha 搜索、Firecrawl 抓取等费用应单列。当前没有接入供应商账单，状态为未知，不计入“免费”。</p><button class="btn" onclick="v4Go('keys')">配置检索与抓取 Key →</button></div></div>`;}
function v4PricesModal(){v4Modal('Token 演示单价 / 每百万 tokens',`<div class="v4-note orange">仅供验证费用计算，不代表任何供应商当前价格。</div><form id="v4-prices-form">${Object.entries(v4Prices).map(([provider,p])=>`<h3 style="margin:13px 0">${provider}</h3><div class="v4-key-grid">${[['input','未缓存输入价'],['cache','缓存输入价'],['output','输出价']].map(([k,t])=>`<div class="v4-field"><label>${t}（元/百万）</label><input type="number" name="${provider}-${k}" min="0" max="10000" step="0.01" required value="${p[k]}"></div>`).join('')}</div>`).join('')}<button class="btn dark" type="submit">保存演示单价并重新计算</button></form>`);}

function v4RenderKeys(){const visible=v4KeyMeta.filter(k=>v4State.keyGroup==='all'||(v4State.keyGroup==='models'&&['deepseek','bigmodel','litellm'].includes(k[0]))||(v4State.keyGroup==='search'&&['tavily','anspire','bocha','firecrawl','jina'].includes(k[0]))||(v4State.keyGroup==='services'&&['feishu','wecom','database'].includes(k[0])));document.getElementById('p-keys').innerHTML=`<div class="topbar"><h1>🔑 Key 与服务配置</h1><span class="sub">LLM · 检索 · 抓取 · 推送 · BettaFish 七槽</span></div><div class="v4-note">入口全部保留。原型中的密钥只放在本次页面内存，刷新清空，不写入 HTML、localStorage 或日志。连接状态需要后端实测；这里提供配置与格式检查。</div><div class="v4-filterbar">${[['all','全部凭据'],['models','模型与代理'],['search','检索与正文'],['services','推送与存储']].map(([id,t])=>`<button class="${v4State.keyGroup===id?'active':''}" data-v4-keygroup="${id}">${t}</button>`).join('')}</div><div class="v4-key-grid">${visible.map(k=>`<div class="v4-key-card" style="--v4-color:${k[3]}"><div class="v4-between"><h4>${k[1]}</h4>${v4Tag(v4Secrets.has(k[0])?'本页已填写':'待配置',v4Secrets.has(k[0])?'g':'gr')}</div><div class="v4-key-status">${k[2]} · 实际连接未测试</div><div class="v4-field" style="margin-top:11px"><label for="v4-secret-${k[0]}">密钥 / 凭据</label><input id="v4-secret-${k[0]}" type="password" autocomplete="off" placeholder="填写本次演示凭据" data-v4-secret="${k[0]}"></div><div class="v4-flex"><button class="btn" data-v4-savekey="${k[0]}">保存到本页内存</button><button class="btn" data-v4-checkkey="${k[0]}">格式检查</button></div></div>`).join('')}</div><div class="v4-panel" style="margin-top:18px"><h3>📡 自部署服务地址</h3><div class="v4-row">${[['newsnow','newsnow 热榜'],['dailyhot','DailyHotApi'],['firecrawl','Firecrawl 正文'],['litellm','LiteLLM 代理']].map(([id,t])=>`<div class="v4-field"><label>${t}</label><input data-v4-service="${id}" value="${v4Esc(v4Services[id])}"></div>`).join('')}</div><button class="btn dark" onclick="v4SaveServices()">保存服务地址草稿</button><p class="v4-label">默认端口沿用原规划，仅作为可编辑地址；不意味着实例已启动或已提供 MCP。</p></div><div class="v4-panel"><div class="v4-between"><h3>🧩 BettaFish 七个 LLM 槽</h3><button class="btn" onclick="v4Go('llm')">供应商管理 ↗</button></div><p class="v4-label">每个槽保留供应商、Base URL、模型 ID 与独立 Key 覆盖。字段命名示意，实施时按原 config.py/.env.example 对齐。</p><div class="v4-slot-grid">${v4Slots.map(s=>`<section class="v4-slot"><h4>${s.name} <span class="mono" style="font-size:10px">${s.id}</span></h4><div class="v4-field"><label>供应商 / 凭据继承</label><select data-v4-slot="${s.id}" data-field="provider">${[['deepseek','DeepSeek'],['bigmodel','BigModel'],['litellm','LiteLLM'],['custom','独立配置']].map(([id,t])=>`<option value="${id}" ${id===s.provider?'selected':''}>${t}</option>`).join('')}</select></div><div class="v4-field"><label>Base URL</label><input value="${v4Esc(s.base)}" data-v4-slot="${s.id}" data-field="base"></div><div class="v4-field"><label>模型 ID</label><input value="${v4Esc(s.model)}" data-v4-slot="${s.id}" data-field="model"></div><div class="v4-field"><label>独立 API Key（可选，留空继承）</label><input type="password" autocomplete="off" data-v4-slotsecret="${s.id}" placeholder="仅当前页面内存"></div></section>`).join('')}</div><button class="btn dark" style="margin-top:14px" onclick="v4SaveSlots()">保存七槽配置草稿</button></div>`;document.querySelectorAll('[data-v4-secret]').forEach(el=>el.value=v4Secrets.get(el.dataset.v4Secret)||'');document.querySelectorAll('[data-v4-slotsecret]').forEach(el=>el.value=v4Secrets.get(el.dataset.v4Slotsecret)||'');}
function v4SaveServices(){const draft={};for(const el of document.querySelectorAll('[data-v4-service]')){try{const u=new URL(el.value.trim());if(!['http:','https:'].includes(u.protocol))throw 0;draft[el.dataset.v4Service]=el.value.trim();}catch{return showToast('服务地址格式无效，未保存任何更改，请填写 HTTP/HTTPS 地址');}}Object.assign(v4Services,draft);showToast('服务地址草稿已保存在本页；未发起连接');}
function v4SaveSlots(){for(const el of document.querySelectorAll('[data-v4-slot]')){const slot=v4Slots.find(s=>s.id===el.dataset.v4Slot);if(slot)slot[el.dataset.field]=el.value;}for(const el of document.querySelectorAll('[data-v4-slotsecret]')){if(el.value.trim())v4Secrets.set(el.dataset.v4Slotsecret,el.value.trim());else v4Secrets.delete(el.dataset.v4Slotsecret);}showToast('七个 LLM 槽草稿已保存；独立 Key 仅在本页内存');}

function v4Modal(title,body){v4PreviousFocus=document.activeElement;document.getElementById('v4-modal-root').innerHTML=`<div class="v4-modal-mask"><section class="v4-modal" role="dialog" aria-modal="true" aria-label="${v4Esc(title)}" tabindex="-1"><header class="v4-modal-head"><h3>${v4Esc(title)}</h3><button class="v4-close" onclick="v4CloseModal()" aria-label="关闭配置弹窗">×</button></header><div class="v4-modal-body">${body}</div></section></div>`;document.querySelector('.v4-modal').focus();}
function v4CloseModal(){document.getElementById('v4-modal-root').innerHTML='';if(v4PreviousFocus?.isConnected)v4PreviousFocus.focus();}
function v4EditRegistry(kind,index){const item=(kind==='skill'?v4Skills:v4Tools)[index];if(!item)return;v4Modal((kind==='skill'?'Skill 规则：':'Tool 契约：')+item.name,`<form id="v4-registry-form" data-kind="${kind}" data-index="${index}"><div class="v4-field"><label>名称</label><input name="name" required value="${v4Esc(item.name)}"></div><div class="v4-field"><label>${kind==='skill'?'提示词 / 适用方法':'参数、返回结构与权限说明'}</label><textarea name="content" style="min-height:180px">${v4Esc(item.content)}</textarea></div><label class="v4-label"><input type="checkbox" name="enabled" ${item.enabled?'checked':''}> 启用此本地配置草稿</label><div class="v4-note">保存只修改本页草稿，不写入 dsh profile，也不执行工具。</div><button class="btn dark" type="submit">保存配置草稿</button></form>`);}
function v4RegistryPanel(kind){const list=kind==='skill'?v4Skills:v4Tools;return `<div class="v4-panel"><div class="v4-between"><h3>${kind==='skill'?'📚 Skill 规则编辑':'🛠 Tool 契约编辑'}</h3><span class="v4-label">能力说明与配置合并为一份</span></div><div class="v4-key-grid">${list.map((x,i)=>`<div class="v4-key-card" style="--v4-color:${v4Colors[i%8]}"><div class="v4-between"><b style="font-size:12px">${v4Esc(x.name)}</b>${v4Tag(x.enabled?'启用':'停用',x.enabled?'g':'gr')}</div><p class="v4-label">${v4Esc(x.content).slice(0,100)}${x.content.length>100?'…':''}</p>${x.original?`<details class="v4-label"><summary>能力与原版说明</summary>${x.original}</details>`:''}${x.permissionHTML?`<div class="v4-field"><label>权限 / 执行策略</label>${x.permissionHTML}</div>`:''}<button class="btn" onclick="v4EditRegistry('${kind}',${i})">编辑${kind==='skill'?'规则':'契约'}</button></div>`).join('')}</div></div>`;}
function v4RefreshRegistry(kind){const host=document.getElementById('v4-'+kind+'-registry');if(host)host.innerHTML=v4RegistryPanel(kind);}
function v4EditMCP(key){const m=MCPS[key];if(!m)return;v4Modal('MCP 配置：'+m.name,`<form id="v4-mcp-form" data-key="${key}"><div class="v4-field"><label>Endpoint / 启动地址</label><input name="endpoint" value="${v4Esc(m.endpoint||'')}" required></div><div class="v4-field"><label>传输方式</label><select name="transport">${['HTTP','HTTP (SSE)','stdio'].map(t=>`<option ${t===m.transport?'selected':''}>${t}</option>`).join('')}</select></div><div class="v4-field"><label>授权说明</label><input name="auth" value="${v4Esc(m.auth||'')}" placeholder="凭据引用名，不填写真实密钥"></div><div class="v4-note">只修改本地定义；不会因为地址填写正确，就显示实际连接成功。</div><button class="btn dark" type="submit">保存 MCP 定义</button></form>`);}
function v4MCPPanel(){return `<div class="v4-panel"><h3>🔌 MCP 服务连接配置</h3><div class="v4-scroll-table"><table><thead><tr><th>服务 / 能力</th><th>Endpoint</th><th>传输</th><th>操作</th></tr></thead><tbody>${Object.entries(MCPS).map(([key,m])=>`<tr><td><b>${v4Esc(m.name)}</b><div class="v4-label">${v4Esc(m.status||'连接状态待实测')}</div><div class="v4-label">${v4Esc(m.summary||'')}</div><div class="v4-label">${v4Esc(m.members||'')}</div></td><td class="mono" style="font-size:11px;overflow-wrap:anywhere">${v4Esc(m.endpoint)}</td><td>${v4Esc(m.transport)}</td><td><button class="btn" onclick="v4EditMCP('${key}')">编辑端点</button></td></tr>`).join('')}</tbody></table></div></div>`;}

function v4PickProvider(id){pickProv(id);v4State.provider=id;const p=PROV[id];const base=document.querySelector('[data-k="BigModel Base URL"]');if(base)base.value=p.url;const field=document.querySelector('#p-llm input[type="password"]');if(field){field.value=v4Secrets.get(id)||'';field.oninput=()=>{if(field.value)v4Secrets.set(id,field.value);else v4Secrets.delete(id);};}v4ImproveLLMButtons();}
function v4CheckProvider(){const url=document.querySelector('[data-k="BigModel Base URL"]')?.value;try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw 0;showToast('URL 格式检查通过；未连接后端，未测试实际模型');}catch{showToast('Base URL 格式无效');}}
function v4AddModel(){const rows=document.getElementById('model-rows'),row=document.createElement('div');row.style.cssText='display:flex;gap:8px;margin-bottom:8px';row.innerHTML='<input class="tsel" style="flex:1" placeholder="输入实际模型 ID"><button class="btn" type="button" onclick="this.parentElement.remove()">删除</button>';rows.append(row);row.querySelector('input').focus();}
function v4SaveProvider(){const p=PROV[v4State.provider];if(!p)return;const base=document.querySelector('[data-k="BigModel Base URL"]');if(base)p.url=base.value;p.m=[...document.querySelectorAll('#model-rows input')].map(el=>el.value).filter(Boolean);const secret=document.querySelector('#p-llm input[type="password"]');if(secret?.value)v4Secrets.set(v4State.provider,secret.value);showToast('供应商与模型草稿已保存到本页，未写入真实服务');}
function v4AddProvider(){v4Modal('添加模型供应商',`<form id="v4-provider-form"><div class="v4-field"><label>供应商名称</label><input name="name" required placeholder="例如：自定义 OpenAI 兼容代理"></div><div class="v4-field"><label>Base URL</label><input name="url" type="url" required placeholder="https://example.com/v1"></div><div class="v4-field"><label>模型 ID</label><input name="model" required placeholder="实际路由模型 ID"></div><button class="btn dark" type="submit">添加本地供应商定义</button></form>`);}
function v4ImproveLLMButtons(){document.querySelectorAll('#p-llm button').forEach(b=>{if(b.textContent.includes('测试连接'))b.onclick=v4CheckProvider;if(b.textContent.includes('添加模型'))b.onclick=v4AddModel;});}
function v4InitLLM(){PROV.litellm={n:'🧭 LiteLLM 代理',url:'http://localhost:4100/v1',m:['GLM-5.3-Flash（填实际代理路由）']};const host=document.querySelector('#p-llm .chatwrap .panel');host.insertAdjacentHTML('beforeend','<div class="conv" onclick="v4PickProvider(\'litellm\')"><div class="ct">🧭 LiteLLM 代理</div><div class="cm">可配置 · 状态待实测</div></div>');document.querySelectorAll('#p-llm .conv[data-p]').forEach(el=>el.onclick=()=>v4PickProvider(el.dataset.p));document.querySelector('#p-llm .sess')?.setAttribute('onclick','v4AddProvider()');const modelRows=document.getElementById('model-rows');modelRows.parentElement.insertAdjacentHTML('beforeend','<button class="btn dark" style="margin-top:10px" onclick="v4SaveProvider()">保存供应商草稿</button><div class="v4-note" style="margin-top:12px">原版 LLM、角色路由和模型列表全部保留。新增 LiteLLM 与七槽配置入口；原型检查格式，不宣称真实连接成功。</div>');v4ImproveLLMButtons();}

const v4Hub=[['llm','🔮 LLM 模型与路由','供应商、Base URL、Key、模型与角色路由','#7c5cf0'],['agent','🤖 Agent 与引擎','原版角色、三研究引擎、Forum 与 Report','#3b6ef5'],['mcp','🔌 MCP 服务','端点、传输、鉴权引用与连接状态','#159cbe'],['skill','📚 Skill 技能','十类工作方法与可编辑规则','#18a678'],['tools','🛠 Tool 工具','八类工具、参数、超时与权限','#e8930c'],['keys','🔑 Key 与服务','检索、抓取、飞书、数据库与 BettaFish 七槽','#e5484d'],['usage','⚡ Token 与费用','输入、输出、缓存、角色分账与费率','#7c5cf0'],['rules','🛡 采集守则','审批、频控、脱敏与域名策略','#18a678'],['approve','✅ 审批中心','查看需要额外授权的任务','#e8930c'],['logs','📋 运行日志','模型、工具和研究事件的审计记录','#7085a8'],['conf','⚙ 系统配置','调度、预警、推送、存储与底座','#3b6ef5']];
renderCustom=function(){parkBack();const kw=(document.querySelector('.csearch')?.value||'').toLowerCase();const rows=v4Hub.filter(r=>(curCat==='all'||r[0]===curCat)&&(!kw||r.join(' ').toLowerCase().includes(kw)));document.getElementById('custom-body').innerHTML='<div class="v4-note">全部配置统一在此管理。选择一个模块进入，模块间可通过顶部标签切换；凭据集中保存，其他页面引用同一配置。</div><div class="v4-hub-grid">'+rows.map(([id,t,d,c])=>`<button class="v4-hub-card" style="--v4-color:${c}" onclick="v4Go('${id}')"><strong>${t}</strong><p>${d}</p></button>`).join('')+'</div>';};

const v4OldOpenDrawer=openDrawer;
openDrawer=function(kind,member){v4OldOpenDrawer(kind,member);if(kind==='report'){const b=document.createElement('button');b.className='btn v4-ask-btn';b.textContent='💬 追问这份报告';b.style.cssText='margin-bottom:13px;width:100%';b.onclick=()=>{closeDrawer();v4AskReport(member||'r1');};document.getElementById('d-body').prepend(b);}};

function v4InitReports(){const host=document.getElementById('p-report');host.querySelector('.guide').insertAdjacentHTML('afterend','<div class="v4-rich-hero"><span class="v4-icon">📄</span><div style="flex:1"><h3>近期 AI 行业舆情研判</h3><p>当前研究的结论、证据、争议与追问入口</p></div><button class="btn" onclick="v4Go(\'research\')">查看研究与证据</button><button class="btn dark" onclick="v4AskReport(\'ai\')">💬 追问这份报告</button></div>');host.querySelectorAll('.cards>.card2').forEach((card,i)=>{const id='r'+(i+1),b=document.createElement('button');b.className='btn v4-ask-btn';b.style.marginTop='10px';b.textContent='💬 追问这份报告';b.onclick=e=>{e.stopPropagation();v4AskReport(id);};card.append(b);});}
function v4UpdateDashboard(){const panel=document.querySelector('#p-dash .tokwrap')?.closest('.panel')||document.getElementById('v4-token-panel');if(panel){panel.id='v4-token-panel';panel.innerHTML=v4TokenSummary();}const t=v4Totals(),k=document.querySelectorAll('#p-dash .kpi')[4];if(k)k.innerHTML=`<div class="t">⚡ Token 用量 / 当前运行样例</div><div class="v" style="color:#7c5cf0">${v4K(t.total)}</div><div class="d">输入 ${v4K(t.input)} · 输出 ${v4K(t.output)} · ${v4Money(t.cost)}</div>`;}
function v4Init(){v4RenderChat();v4RenderUsage();v4RenderKeys();v4UpdateDashboard();v4InitReports();v4InitLLM();document.getElementById('p-skill').insertAdjacentHTML('beforeend','<div id="v4-skill-registry"></div>');document.getElementById('p-tools').insertAdjacentHTML('beforeend','<div id="v4-tool-registry"></div>');v4RefreshRegistry('skill');v4RefreshRegistry('tool');document.getElementById('p-mcp').insertAdjacentHTML('beforeend','<div id="v4-mcp-edit">'+v4MCPPanel()+'</div>');const chips=document.querySelector('#p-custom .custombar');chips.insertAdjacentHTML('beforeend','<span class="chipc" data-c="keys" onclick="pickCustom(\'keys\')">🔑 Key</span><span class="chipc" data-c="usage" onclick="pickCustom(\'usage\')">⚡ Token</span>');document.querySelector('#p-dash .newtask').onclick=v4StartResearch;document.querySelectorAll('a[data-p]').forEach(a=>{a.setAttribute('role','button');a.tabIndex=0;});document.querySelector('.usercard .up').textContent='Token 账本 / 用量与额度';document.querySelector('.usercard').onclick=()=>v4Go('usage');}

document.addEventListener('click',e=>{const x=e.target.closest('button,a,[data-p]');if(!x)return;if(x.dataset.v4Prompt)return v4Send(x.dataset.v4Prompt);if(x.dataset.v4Session)return v4SelectSession(x.dataset.v4Session);if(x.dataset.v4Mode){const id=x.dataset.v4Mode==='report'?'report-ai':x.dataset.v4Mode==='general'?'general':'research-help';return v4SelectSession(id);}if(x.dataset.v4Evidence)return v4ShowEvidence(x.dataset.v4Evidence);if(x.dataset.v4Usage){v4State.usageFilter=x.dataset.v4Usage;return v4RenderUsage();}if(x.dataset.v4Keygroup){v4State.keyGroup=x.dataset.v4Keygroup;return v4RenderKeys();}if(x.dataset.v4Savekey){const id=x.dataset.v4Savekey,value=document.getElementById('v4-secret-'+id).value.trim();if(value)v4Secrets.set(id,value);else v4Secrets.delete(id);v4RenderKeys();return showToast('凭据已保留在本页内存；未调用实际服务');}if(x.dataset.v4Checkkey){const id=x.dataset.v4Checkkey,value=document.getElementById('v4-secret-'+id).value.trim();return showToast(value?'字段已填写；真实鉴权需要后端测试，未发起请求':'该字段为空，尚未配置凭据');}});
document.addEventListener('submit',e=>{if(e.target.matches('.v4-chat-form')){e.preventDefault();const field=e.target.querySelector('textarea');v4Send(field.value);return;}if(e.target.id==='v4-prices-form'){e.preventDefault();const d=new FormData(e.target);for(const provider of Object.keys(v4Prices))for(const k of ['input','cache','output']){const n=Number(d.get(provider+'-'+k));if(!Number.isFinite(n)||n<0)return;v4Prices[provider][k]=n;}v4CloseModal();v4RenderUsage();v4UpdateDashboard();return showToast('演示费率已更新，费用由代码重新计算');}if(e.target.id==='v4-registry-form'){e.preventDefault();const f=e.target,d=new FormData(f),list=f.dataset.kind==='skill'?v4Skills:v4Tools,item=list[Number(f.dataset.index)];item.name=String(d.get('name')).trim();item.content=String(d.get('content'));item.enabled=d.has('enabled');v4CloseModal();v4RefreshRegistry(f.dataset.kind);return showToast('本地配置草稿已更新');}if(e.target.id==='v4-mcp-form'){e.preventDefault();const d=new FormData(e.target),m=MCPS[e.target.dataset.key];m.endpoint=String(d.get('endpoint'));m.transport=String(d.get('transport'));m.auth=String(d.get('auth'));m.status='未实测 · 本地定义';v4CloseModal();document.getElementById('v4-mcp-edit').innerHTML=v4MCPPanel();return showToast('MCP 定义已保存，未进行真实握手');}if(e.target.id==='v4-provider-form'){e.preventDefault();const d=new FormData(e.target),id='custom'+Date.now(),n=String(d.get('name'));PROV[id]={n,url:String(d.get('url')),m:[String(d.get('model'))]};const host=document.querySelector('#p-llm .chatwrap .panel'),card=document.createElement('div');card.className='conv';card.innerHTML='<div class="ct">🔮 '+v4Esc(n)+'</div><div class="cm">本地自定义 · 待实测</div>';card.onclick=()=>v4PickProvider(id);host.append(card);v4CloseModal();v4PickProvider(id);showToast('已添加本地供应商定义');}});
document.addEventListener('keydown',e=>{if(e.target.matches('.v4-chat-form textarea')&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}if(e.target.matches('a[data-p]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.click();}if(e.key==='Escape'){v4CloseModal();if(v4State.quick){v4State.quick=false;v4RenderQuick();}}const modal=document.querySelector('.v4-modal');if(modal&&e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&(document.activeElement===first||document.activeElement===modal)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===modal)){e.preventDefault();first.focus();}}});
window.addEventListener('message',e=>{const frame=document.getElementById('v4-research-frame');if(e.source!==frame?.contentWindow)return;if(e.data?.kind==='diting-v4:snapshot'){const d=e.data;if(Array.isArray(d.claims)&&Array.isArray(d.evidence)){v4Research={topic:String(d.topic),phase:Number(d.phase),claims:d.claims,evidence:d.evidence};v4Reports.ai.title=v4Research.topic;}}if(e.data?.kind==='diting-v4:ask-report')v4AskReport('ai');});
document.getElementById('v4-research-frame').addEventListener('load',()=>document.getElementById('v4-research-frame').contentWindow.postMessage({kind:'diting-v4:request-snapshot'},'*'));
v4Init();

function v4RoleCosts(rows,t){const groups={};for(const r of rows){const g=groups[r.role]||(groups[r.role]={cost:0,known:0,unknown:0});const c=v4Cost(r);if(c===null)g.unknown++;else{g.cost+=c;g.known++;}}return Object.entries(groups).map(([role,g],i)=>`<div class="v4-bar-row"><span>${v4Esc(role)}</span><div class="v4-progress"><i style="width:${t.cost?g.cost/t.cost*100:0}%;background:${v4Colors[i%8]}"></i></div><b style="font-size:11px;text-align:right">${g.known?v4Money(g.cost):'未知'}${g.unknown&&g.known?' + 未知':''}</b></div>`).join('');}
